/**
 * A hand-written `LocationArtifact` for testing the resolver.
 *
 * The real artifact is generated by the pipeline, which a parallel agent is
 * building. This fixture exists so the resolver can be finished and measured
 * before that lands, and so every rule has a case that would fail if the rule
 * were removed. Nothing in the resolver depends on this file; it depends only
 * on the shape in `../types.ts`.
 *
 * Rules this fixture is built to exercise, each with a real place behind it:
 *
 *  - two-letter collisions: DE, IL, MA, LA, CO, CA, GA all appear as BOTH a
 *    country code and a US state code, which is the whole difficulty
 *  - a city alias that must never act as a qualifier: `LA` for Los Angeles
 *  - candidates removed by the prune rule: Paris KY and Buffalo MN have no
 *    airport at all, Hartford WI has one 210 km away
 *  - a same-country near-tie (three Springfields) and a same-country clear
 *    winner (Portland OR over Portland ME)
 *  - a multi-country contest with the WIDEST prominence gap (Paris)
 *  - the ten spellings the naive normaliser was measured to miss
 *  - a shared IATA code claimed by two places (LAX: Los Angeles and Burbank)
 *  - short names (`Ba`, `Ho`, `Ely`) that a careless fuzzy path would propose
 *
 * Population figures are real; `airportRank` is annual passengers at the
 * airports the place is the primary city for, which is how the pipeline's
 * "largest city within radius" assignment behaves. `null` means the place is
 * served by someone else's airport.
 */

import type { LocationArtifact, Place, PlaceAirport, PlaceKind } from '../types';

type AirportSpec = [iata: string, km: number, servesPlace?: boolean];

type Row = {
  id: string;
  name: string;
  kind: PlaceKind;
  country: string;
  admin?: string | null;
  lat: number;
  lon: number;
  pop?: number | null;
  rank?: number | null;
  metro?: string | null;
  aliases?: string[];
  /**
   * The hand-written subset of `aliases`. Listed separately here for the same
   * reason the artifact carries it separately: a curated alias is a decision
   * and outranks a dataset alternate name. Entries must also appear in
   * `aliases`, which `place()` enforces.
   */
  curated?: string[];
  airports?: AirportSpec[];
};

function place(row: Row): Place {
  const airports: PlaceAirport[] = (row.airports ?? []).map(([iata, km, serves]) => ({
    iata,
    km,
    servesPlace: serves ?? true,
  }));
  const aliases = row.aliases ?? [];
  const curated = row.curated ?? [];
  // A fixture that drifts from the contract is worse than no fixture, and this
  // is the one invariant a typo can break silently.
  for (const entry of curated) {
    if (!aliases.includes(entry)) {
      throw new Error(`fixture ${row.id}: curated alias ${entry} is missing from aliases`);
    }
  }
  return {
    id: row.id,
    name: row.name,
    aliases,
    curatedAliases: curated,
    kind: row.kind,
    country: row.country,
    admin: row.admin ?? null,
    lat: row.lat,
    lon: row.lon,
    population: row.pop ?? null,
    airportRank: row.rank ?? null,
    metro: row.metro ?? null,
    airports,
  };
}

